/*
 * IR Remote Decoder with LCD Display
 * Receives NEC IR codes from a remote control and displays
 * the hex values on a 16x2 I2C LCD.
 *
 * Wiring:
 *   TSOP4838 OUT -> D2
 *   TSOP4838 VCC -> 5V, GND -> GND
 *   LCD I2C SDA -> A4, SCL -> A5
 *   LCD I2C VCC -> 5V, GND -> GND
 *   IR Remote - click any button on the canvas remote to send a code.
 */

#include <IRremote.h>
#include <Wire.h>
#include <LiquidCrystal_I2C.h>

const int RECV_PIN = 2;
IRrecv irrecv(RECV_PIN);
decode_results results;
LiquidCrystal_I2C lcd(0x27, 16, 2);

unsigned long lastCode = 0;
int pressCount = 0;

void setup() {
  Serial.begin(115200);
  irrecv.enableIRIn();

  lcd.init();
  lcd.backlight();
  lcd.setCursor(0, 0);
  lcd.print("IR Remote Decoder");
  lcd.setCursor(0, 1);
  lcd.print("Press a button...");

  Serial.println("IR Remote Decoder with LCD ready");
  Serial.println("Press a button on the remote...");
}

